mapper.select:
SELECT *
FROM lunaerp_finance_supplier_recon
WHERE id = #{id}
  AND deleted = 1
  AND status = 'DRAFT'
  AND tenant_id = #{tenantId}

mapper.update:
UPDATE lunaerp_finance_supplier_recon
SET deleted = 0,
    status = 'DRAFT',
    updater = #{updater},
    update_time = #{updateTime}
WHERE id = #{id}
  AND deleted = 1
  AND status = 'DRAFT'
  AND tenant_id = #{tenantId}

mapper.delete:
DELETE FROM lunaerp_finance_supplier_recon
WHERE id = #{id}
  AND deleted = 1
  AND status = 'DRAFT'
  AND tenant_id = #{tenantId}

mapper.select:
SELECT COUNT(1)
FROM lunaerp_finance_payment_apply
WHERE recon_id = #{reconId}
  AND deleted = 0
  AND tenant_id = #{tenantId}

mapper.update:
UPDATE lunaerp_finance_supplier_recon
SET status = 'CONFIRMED',
    confirmed_by = #{userId},
    confirmed_at = #{now},
    updater = CAST(#{userId} AS VARCHAR),
    update_time = #{now}
WHERE id = #{id}
  AND status = 'DRAFT'
  AND deleted = 0
  AND tenant_id = #{tenantId}

UPDATE lunaerp_finance_supplier_recon
SET status = 'CANCELLED',
    cancelled_by = #{userId},
    cancelled_at = #{now},
    updater = CAST(#{userId} AS VARCHAR),
    update_time = #{now}
WHERE id = #{id}
  AND status = 'CONFIRMED'
  AND deleted = 0
  AND tenant_id = #{tenantId}
